/* Owner-approved 2026-08-30. Order is deliberate: commonest first, "Other"
   always last. `intercept` marks the one option that should not cancel — a
   scheduling conflict is a booking that can be kept. */
export const REQUESTER_REASONS = [
  { key: "no_longer_need", label: "No longer need it" },
  { key: "found_another", label: "Found another option / doing it myself" },
  { key: "wrong_details", label: "Wrong details in my request" },
  {
    key: "scheduling_conflict",
    label: "Scheduling conflict — need a different time",
    intercept: true,
  },
  { key: "gopher_concern", label: "Concern about the worker" }, // John 10/12: "should be worker"; the key is unchanged
  { key: "other", label: "Other", other: true },
];

/**
 * G40-188 (a) — the same menu, minus the two answers that contradict the screen.
 *
 * ⛔ A REPOST IS NOT A CANCELLATION, AND TWO OF THE CANCEL REASONS SAY IT IS.
 * "No longer need it" and "Found another option / doing it myself" both mean
 * "I do not want this job" — on a screen whose entire premise is that the
 * requester DOES still want it and is only changing who does it. Offering them
 * there is not merely untidy: whatever is picked is written to
 * `orders.cancellation_reason` and emailed verbatim to the Gopher, so a worker
 * would be told the request was no longer needed while watching it go straight
 * back onto the board. It also poisons the field for anyone later counting why
 * requesters walk away.
 *
 * The four that survive are the ones that are true of a repost: wrong details,
 * a timing clash, a concern about that particular Gopher, and Other.
 *
 * ⚠️ Derived from REQUESTER_REASONS rather than retyped, so a label edited for
 * the cancel sheet cannot silently drift from the one the repost sheet shows.
 */
export const REPOST_EXCLUDED_KEYS = ["no_longer_need", "found_another"];

export const REPOST_REASONS = REQUESTER_REASONS.filter(
  (r) => !REPOST_EXCLUDED_KEYS.includes(r.key),
);

export const MAX_REASON_LENGTH = 150;

export const MIN_REASON_WORDS = 3;

/**
 * The Gopher sheet has always required 3 WORDS, not 3 characters — its own copy
 * said so, and the gate was `minCharacter <= 2` where the value counted words.
 * That bar is kept and now applies only to "Other": picking a listed reason is
 * already a complete answer.
 */
export const countWords = (text) =>
  String(text || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean).length;

export const isReasonComplete = (reason, otherText) => {
  if (!reason) return false;
  if (!reason.other) return true;
  return countWords(otherText) >= MIN_REASON_WORDS;
};

/**
 * The Gopher side has no list, so the 3-word bar is the whole gate. Kept as a
 * named export rather than an inline `countWords(x) >= 3` in the component so
 * that the rule a worker is held to lives beside the requester's, in the file
 * the tests already cover.
 */
export const isFreeTextComplete = (text) =>
  countWords(text) >= MIN_REASON_WORDS;

/**
 * G40-188 (a) — how long before a scheduled request starts a requester may send
 * it back out WITHOUT explaining themselves.
 *
 * Owner, 2026-09-10: "I would prefer the requester not have to give a reason if
 * the request is outside of 24 hours from scheduled date. IF the request is
 * inside the time, they do need to give a reason."
 *
 * ⛔ THIS IS THE CLIENT HALF OF A RULE THE SERVER ALSO ENFORCES
 * (controllers/order/repost.js). Duplicated deliberately, because the two
 * answer different questions: this one decides what the requester is SHOWN, the
 * server's decides what is ACCEPTED, and a client is not a thing the backend
 * gets to trust. They must agree on the boundary, which is why the constant
 * lives here as a named export instead of a `24` buried in a component.
 *
 * ⚠️ FAILS TOWARD ASKING. A missing or unparseable time returns true. The two
 * ways to be wrong are not symmetric: a needless prompt costs a requester one
 * sentence, while a skipped one costs a Gopher the only explanation they get
 * for losing a job they had held their day for.
 */
export const REPOST_FREE_REASON_HOURS = 24;

export const repostNeedsReason = (scheduledAt) => {
  const ms = scheduledAt ? new Date(scheduledAt).getTime() : NaN;
  if (Number.isNaN(ms)) return true;
  return !(ms - Date.now() > REPOST_FREE_REASON_HOURS * 60 * 60 * 1000);
};
